/*selectMasterMdCpNewRegAgntcmpyInfoPopList*/ SELECT ROWNUM NUM, L.FLAG, L.COM_CODE, L.COM_NAME_LOC, L.IRS_NO, L.CEO_NAME_LOC, L.TEL_NO, L.FAX_NO, L.ADDRESS_LOC, L.HP_ADDRESS, L.USER_ID, L.USER_NAME_LOC, L.PHONE_NUMBER, L.MOBILE_PHONE, L.EMAIL, L.MDM_CONFIRM_TYPE FROM ( SELECT 'A' AS FLAG, A.COM_CODE, A.COM_NAME_LOC, A.IRS_NO, A.CEO_NAME_LOC, A.TEL_NO, A.FAX_NO, A.ADDRESS_LOC, A.HP_ADDRESS, B.USER_ID, B.USER_NAME_LOC, B.PHONE_NUMBER, B.MOBILE_PHONE, B.EMAIL, DECODE(A.MDM_CONFIRM_TYPE,'F','제재이력업체','D','중복업체','T','등록가능','E','기타') AS MDM_CONFIRM_TYPE FROM ICOMCMPY A, ICOMLUSR B WHERE A.COM_CODE = #{com_code} AND A.COM_CODE = B.COM_CODE AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND A.BUSINESS_COND = 'S' UNION ALL SELECT 'B' AS FLAG, C.COM_CODE, C.COM_NAME_LOC, C.IRS_NO, C.CEO_NAME_LOC, C.TEL_NO, C.FAX_NO, C.ADDRESS_LOC, C.HP_ADDRESS, D.USER_ID, D.USER_NAME_LOC, D.PHONE_NUMBER, D.MOBILE_PHONE, D.EMAIL, DECODE(A.MDM_CONFIRM_TYPE,'F','제재이력업체','D','중복업체','T','등록가능','E','기타') AS MDM_CONFIRM_TYPE FROM ICOMCMPY A, ICOMLUSR B, ICOMCMPY C, ICOMLUSR D WHERE 1=1 AND A.BUSINESS_COND = 'S' AND C.BUSINESS_COND = 'S' AND A.COM_CODE = #{com_code} AND A.COM_CODE = B.COM_CODE AND A.COM_CODE <> C.COM_CODE AND C.COM_CODE = D.COM_CODE
AND A.COM_CODE NOT IN
#{item}
AND C.COM_CODE NOT IN
#{item}
AND ( A.COM_NAME_LOC2 = C.COM_NAME_LOC2 OR TRIM(SUBSTR(A.TEL_NO,LENGTHB(A.TEL_NO)-3 ,4)) = TRIM(SUBSTR(C.TEL_NO,LENGTHB(C.TEL_NO)-3 ,4)) OR TRIM(SUBSTR(A.FAX_NO,LENGTHB(A.FAX_NO)-3 ,4)) = TRIM(SUBSTR(C.FAX_NO,LENGTHB(C.FAX_NO)-3 ,4)) OR TRIM(SUBSTR(B.PHONE_NUMBER,LENGTHB(B.PHONE_NUMBER)-3 ,4)) = TRIM(SUBSTR(D.PHONE_NUMBER,LENGTHB(D.PHONE_NUMBER)-3 ,4)) OR TRIM(SUBSTR(B.MOBILE_PHONE,LENGTHB(B.MOBILE_PHONE)-3 ,4)) = TRIM(SUBSTR(D.MOBILE_PHONE,LENGTHB(D.MOBILE_PHONE)-3 ,4)) OR TRIM(A.CEO_NAME_LOC) = TRIM(C.CEO_NAME_LOC) OR TRIM(B.USER_NAME_LOC) = TRIM(D.USER_NAME_LOC) OR TRIM(UPPER(F_SPLIT(B.EMAIL,'@',1))) = TRIM(UPPER(F_SPLIT(D.EMAIL,'@',1))) ) ORDER BY FLAG, COM_CODE, USER_ID )L


/* selectMasterMdCpNewRegAgntcmpyInfoMDMList */
SELECT DECODE(COUNT(CODE),0,'NO','YES') AS MDM_FLAG
FROM ICOMCOD2
WHERE TYPE = 'MDM' AND CODE = #{st_user_id}

